@section('content')<div class="orientation-shell"><div class="d-flex align-items-center mb-3"><div><span class="text-success fw-bold small">QUESTIONNAIRE RIASEC</span><h2 class="h3 fw-bold mb-0">Découvrez vos affinités</h2></div><strong id="stepLabel" class="ms-auto text-success">1 / {{ $questions->count()+1 }}</strong></div><div class="progress mb-4" style="height:8px"><div id="progressBar" class="progress-bar bg-success" style="width:0"></div></div>@if($errors->any())<div class="alert alert-danger">{{ $errors->first() }}</div>@endif<form method="POST" action="{{ route('student.orientation.store') }}">@csrf<div class="surface-card p-4 p-md-5 step-card active" data-step="1"><h3 class="h5 fw-bold mb-4">Votre parcours académique</h3><div class="row g-3"><div class="col-md-6"><label class="form-label">Série du BAC *</label><select name="bac_serie_id" class="form-select" required><option value="">Choisir</option>@foreach($series as $serie)<option value="{{ $serie->id }}" @selected((string)old('bac_serie_id',auth()->user()->bac_serie_id) === (string)$serie->id)>{{ $serie->code }} — {{ $serie->name }}</option>@endforeach</select></div><div class="col-md-6"><label class="form-label">Année du BAC</label><input class="form-control" value="{{ auth()->user()->bac_year }}" disabled></div></div><h4 class="h6 fw-bold mt-4">Vos moyennes en BAC (sur 20)</h4><div class="row g-2">@foreach(['Mathématiques','Physique-Chimie','Sciences de la Vie et de la Terre','Français','Philosophie','Économie'] as $subject)<div class="col-6 col-md-4"><label class="form-label small">{{ $subject }}</label><input type="number" step="0.5" min="0" max="20" name="grades[{{ $subject }}]" value="{{ old("grades.$subject") }}" class="form-control" placeholder="0 à 20"></div>@endforeach</div></div>@foreach($questions as $index=>$question)<div class="surface-card p-4 p-md-5 step-card" data-step="{{ $index+2 }}"><span class="badge bg-success-subtle text-success mb-3">Question {{ $index+1 }}</span><h3 class="h5 fw-bold mb-4">{{ $question->question_text }}</h3><div class="d-grid gap-3">@foreach($question->options as $option)<label class="choice d-flex gap-3"><input type="radio" name="answers[{{ $question->id }}]" value="{{ $option['dimension'] }}" required @checked(old("answers.$question->id") === $option['dimension'])><span>{{ $option['text'] }}</span></label>@endforeach</div></div>@endforeach<div class="surface-card p-4 p-md-5 step-card" data-step="{{ $questions->count()+2 }}"><h3 class="h5 fw-bold mb-3">Vos centres d’intérêt</h3><p class="text-muted">Sélectionnez quelques thèmes. Ils rendront vos recommandations plus précises.</p><div class="d-flex flex-wrap gap-2">@foreach($interests as $interest)<label class="interest-chip"><input type="checkbox" name="selected_interest_ids[]" value="{{ $interest->id }}"><span>{{ $interest->name }}</span></label>@endforeach</div></div><div class="d-flex justify-content-between mt-4"><button type="button" id="backBtn" class="btn btn-light border px-4" disabled><i class="bi bi-arrow-left me-2"></i>Retour</button><button type="button" id="nextBtn" class="btn btn-orange px-4">Suivant<i class="bi bi-arrow-right ms-2"></i></button><button type="submit" id="submitBtn" class="btn btn-orange px-4 d-none"><i class="bi bi-stars me-2"></i>Calculer mon profil</button></div></form></div>
