@section('scripts')<script>const cards=[...document.querySelectorAll('.step-card')],back=document.getElementById('backBtn'),next=document.getElementById('nextBtn'),submit=document.getElementById('submitBtn'),bar=document.getElementById('progressBar'),label=document.getElementById('stepLabel');let step=0;function show(){cards.forEach((c,i)=>c.classList.toggle('active',i===step));back.disabled=step===0;const last=step===cards.length-1;next.classList.toggle('d-none',last);submit.classList.toggle('d-none',!last);bar.style.width=`${Math.round(step/(cards.length-1)*100)}%`;label.textContent=`${step+1} / ${cards.length}`}next.addEventListener('click',()=>{const required=[...cards[step].querySelectorAll('[required]')];if(required.length&&!required.every(el=>el.type==='radio' ? cards[step].querySelector(`input[name="${CSS.escape(el.name)}"]:checked`) : el.value)){cards[step].scrollIntoView({behavior:'smooth'});required.find(el=>el.type==='radio' ? !cards[step].querySelector(`input[name="${CSS.escape(el.name)}"]:checked`) : !el.value)?.focus();return}step=Math.min(step+1,cards.length-1);show();window.scrollTo({top:0,behavior:'smooth'})});back.addEventListener('click',()=>{step=Math.max(0,step-1);show();window.scrollTo({top:0,behavior:'smooth'})});show();</script>@endsection
